mapper.sql:
AND c.app_id=#{q.appId}
AND c.platform=#{q.platform}
AND c.app_version=#{q.appVersion}
AND c.crash_time BETWEEN #{q.beginTime} AND #{q.endTime}

AND t.app_id=#{q.appId}
AND t.platform=#{q.platform}
AND t.app_version=#{q.appVersion}
AND t.add_time BETWEEN #{q.beginTime} AND #{q.endTime}

AND p.app_id=#{q.appId}
AND p.platform=#{q.platform}
AND p.app_version=#{q.appVersion}
AND p.last_poll_time BETWEEN #{q.beginTime} AND #{q.endTime}

AND h.app_id=#{q.appId}
AND h.platform=#{q.platform}
AND h.app_version=#{q.appVersion}
AND h.occurred_at BETWEEN #{q.beginTime} AND #{q.endTime}

mapper.select:
SELECT
    (SELECT COUNT(*) FROM logan_crash c WHERE c.kind <> 'anr'
        ) AS crashEvents,
    (SELECT COUNT(DISTINCT c.device_id) FROM logan_crash c WHERE c.kind <> 'anr'
        ) AS crashDevices,
    (SELECT COUNT(DISTINCT c.fingerprint) FROM logan_crash c WHERE c.kind <> 'anr'
        ) AS crashIssues,
    (SELECT COUNT(*) FROM logan_crash c WHERE c.kind = 'anr'
        ) AS anrEvents,
    (SELECT COUNT(DISTINCT c.device_id) FROM logan_crash c WHERE c.kind = 'anr'
        ) AS anrDevices,
    (SELECT COUNT(DISTINCT c.fingerprint) FROM logan_crash c WHERE c.kind = 'anr'
        ) AS anrIssues,
    (SELECT COUNT(*) FROM logan_http h WHERE (h.status >= 400 OR (h.err_kind IS NOT NULL AND h.err_kind <> ''))
        ) AS httpFailed,
    (SELECT COUNT(*) FROM logan_http h WHERE h.slow = 1
        ) AS httpSlow

SELECT c.fingerprint AS fingerprint,
       COUNT(*) AS events,
       COUNT(DISTINCT c.device_id) AS devices
FROM logan_crash c
WHERE c.crash_time BETWEEN #{beginTime} AND #{endTime}
AND c.app_id=#{q.appId}
AND c.platform=#{q.platform}
AND c.app_version=#{q.appVersion}
AND c.fingerprint IN
#{fp}
GROUP BY c.fingerprint

SELECT v FROM (
    SELECT DISTINCT c.app_version AS v FROM logan_crash c
     WHERE c.app_version IS NOT NULL AND c.app_version <> ''
       AND c.app_id=#{q.appId}
       AND c.platform=#{q.platform}
     UNION
    SELECT DISTINCT t.app_version AS v FROM logan_task t
     WHERE t.app_version IS NOT NULL AND t.app_version <> ''
       AND t.app_id=#{q.appId}
       AND t.platform=#{q.platform}
) x
ORDER BY v DESC
LIMIT 100
